                ["bt.fled.reply"] = new[] { "히히, 내 다리가 신들보다 빨랐지!", "도망 아니야! 작전이었다고!", "다음엔 덤빌 거야! ...정말로." },
                ["bt.gods.open"] = new[] { "{partner}, 오딘이 방금 웃었어. 들었어?", "로키가 또 무슨 장난을 칠까, 히히.", "신들은 우리 이야기를 듣고 있어. 조심해, 히히.", "{partner}, 저 구름 모양 봐! 슬레이프니르야!", "오딘의 까마귀가 나한테 윙크했어. 히히.", "토르가 망치를 떨어뜨리면 우리 머리 위로 떨어질까?", "로키는 나랑 친구가 될 수 있을 것 같아. 히히.", "{partner}, 신들한테 제물 바칠래? 내 버섯 줄게.", "어젯밤 꿈에 프레이가 나왔어! 진짜야!", "이그드라실 뿌리를 따라가면 신들 집이 나올까?", "히히, 방금 바람이 내 귀에 비밀을 속삭였어.", "발할라에 가면 미드가 강처럼 흐른대!", "룬을 새기면 신들이 답장을 해 줄까?", "{partner}, 오딘은 눈 하나로 어떻게 다 보지?", "히히, 신들도 가끔 장난치고 싶을 거야." },
                ["bt.gods.reply"] = new[] { "당연하지! 신들은 늘 여기 있어.", "히히, 의심하면 벌 받아!", "오딘은 나를 좋아해. 너도 조금.", "히히, 신들이 듣고 있어!", "맞아 맞아! 나도 그렇게 생각했어!", "오딘한테 물어보자! 대답은 까마귀가 해 줄 거야.", "신들은 다 알고 있어. 히히.", "쉿! 너무 크게 말하면 로키가 와!", "난 믿어! 완전 믿어!", "히히, 그건 비밀이야.", "우와, 그거 멋지다!", "신들한테 미드 한 잔 바치자!", "그럼 오늘 밤 꿈에서 물어볼게!", "히히, 신들은 장난을 좋아해.", "신들도 우리를 좋아할 거야. 특히 나!" },
                ["bt.home.open"] = new[] { "우리 집 최고! 히히.", "{partner}, 여기다 배 창고 짓자!", "집에 나무 냄새가 가득해. 좋아!", "{partner}, 지붕에 용 조각 달자! 히히.", "집에서 나무 냄새 나는 거 너무 좋아!", "밤에 불 피우면 그림자가 춤춰. 봤어?", "우리 집 벽에 룬 새겨도 돼?", "{partner}, 집 지키는 정령이 있대! 히히.", "여기 처음 왔을 때 기억나? 풀밭뿐이었잖아!", "상자에 몰래 버섯 숨겨 놨어. 히히.", "집 옆에 배 띄울 데도 만들자!", "굴뚝 연기가 꼭 용 숨결 같아!", "히히, 여기 내 자리야! 아무도 앉지 마!", "{partner}, 우리 집 이름 지어 주자!", "집 지붕 위에서 별 보는 거 최고야!" },
                ["bt.home.reply"] = new[] { "히히, 그럼 내가 장식할게!", "집도 좋지만 모험이 더 좋아!", "여기 신들도 살면 좋겠다.", "히히, 좋아 좋아!", "우리 집이 세상에서 제일 멋져!", "그럼 내가 망치 들게!", "장식은 나한테 맡겨!", "히히, 신들도 부러워할걸?", "더 크게! 더 높게!", "좋아! 근데 먼저 놀자!", "히히, 내 자리 비워 둬!", "집은 좋아. 그래도 바다가 더 좋아!", "우리가 지은 집이야! 히히.", "불 옆에서 이야기하자!", "그거 멋지다! 당장 하자!" },
                ["bt.item.open"] = new[] { "{item}! {dir}에 산더미야, 히히.", "{partner}, {dir} {item} 기억나? 내가 찾았잖아!", "{item|은} {dir}! 신들이 거기 쌓아 뒀어." },
