                ["bt.night.open"] = new[] { "밤이다! 늑대들이 노래해, 히히.", "{partner}, 저 별 봐! 오딘의 눈이야!", "밤엔 유령이 나온대. 히히, 무섭지?" },
                ["bt.night.reply"] = new[] { "히히, 안 무서워!", "별 하나 따다 줄까?", "잠은 발할라에서 자면 돼!" },
                ["bt.pit.open"] = new[] { "{dir} 구덩이! 거기 빠졌을 때 진짜 무서웠어, 히히.", "{partner}, {dir} 구덩이 조심해! 땅이 입을 벌리고 있어." },
                ["bt.pit.reply"] = new[] { "히히, 나 거기서 춤췄잖아!", "그 구덩이, 로키가 판 게 분명해!" },
                ["bt.sea.open"] = new[] { "배! 큰 배를 만들고 싶어. 용머리를 단 거!", "{partner}, 내가 배 만들면 같이 타자, 히히.", "바다는 신들의 길이야. 언젠가 건널 거야.", "바다 냄새! 짭짤해서 좋아!", "{partner}, 물고기들도 노래 부를까? 히히.", "파도가 나를 부르고 있어! 들려?", "배 만들 나무 봤어! 아주 곧은 거!", "바다뱀 등에 타 보고 싶어. 히히.", "{partner}, 돛에 용 그려 줄까?", "저 끝까지 노 저으면 세상 끝이 보일까?", "배는 살아 있어. 나무가 기억하거든.", "히히, 바다에 뛰어들면 시원하겠다!", "별을 따라가면 신들의 섬이 나올 거야!", "내 배는 바람보다 빠를 거야!", "{partner}, 바다 위에서 자 본 적 있어?" },
                ["bt.sea.reply"] = new[] { "히히, 내가 만들게! 제일 빠른 배로!", "바다다! 상상만 해도 신나!", "배 이야기는 언제나 좋아!", "가자! 지금 당장!", "히히, 내가 키 잡을게!", "우와, 상상만 해도 신난다!", "바다는 우리 거야!", "배는 내가 만들게, 넌 노 저어!", "히히, 파도 타기다!", "바다 너머엔 보물이 있을 거야!", "좋아 좋아! 용머리 꼭 달자!", "히히, 멀미하면 안 돼!", "바다 이야기 더 해 줘!", "바람아 불어라! 히히.", "신들의 길로 출발!" },
                ["bt.skill.open"] = new[] { "내 {skill} {level}! 히히, 대단하지?", "{partner}, 나 {skill} {level|이야}! 네 {pskill|은} {plevel}이지? 히히.", "{skill} {level}! 신들도 놀라셨을걸." },
                ["bt.skill.reply"] = new[] { "히히, 나도 곧 따라잡을 거야!", "흥, 내 {skill|은} {level|이야}! 그 정도야 나도 해!", "축하해! 신들이 기뻐하실 거야." },
